create table public.legal_documents(
 document_key text primary key check(document_key in ('privacy','terms')),
 lock_version bigint not null default 0 check(lock_version>=0),
 revision_count integer not null default 1 check(revision_count>=1),
 updated_at timestamptz not null default now(),
 last_editor uuid references auth.users(id) on delete set null
);
create table public.legal_revisions(
 id uuid primary key default gen_random_uuid(),
 document_key text not null references public.legal_documents(document_key),
 version integer not null check(version>=1), content jsonb not null,
 created_at timestamptz not null default now(), approved_at timestamptz, revoked_at timestamptz,
 unique(document_key,version),unique(document_key,id),
 check(revoked_at is null or approved_at is not null)
);
create index legal_current_publication on public.legal_revisions(document_key,version desc) where approved_at is not null and revoked_at is null;
create table public.legal_events(
 id uuid primary key default gen_random_uuid(),document_key text not null,
 revision_id uuid not null,action text not null check(action in ('save','publish','revoke','restore')),
 actor_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),
 foreign key(document_key,revision_id) references public.legal_revisions(document_key,id)
);
create index legal_event_history on public.legal_events(document_key,created_at desc);
alter table public.legal_documents enable row level security;
alter table public.legal_revisions enable row level security;
alter table public.legal_events enable row level security;
revoke all on public.legal_documents,public.legal_revisions,public.legal_events from public,anon,authenticated;
grant select,update on public.legal_documents to authenticated;
grant select,insert,update on public.legal_revisions to authenticated;
grant select,insert on public.legal_events to authenticated;
grant select on public.legal_revisions to anon;
create policy legal_head_admin on public.legal_documents for all to authenticated using((select unseen_private.is_admin())) with check((select unseen_private.is_admin()));
create policy legal_revision_anon on public.legal_revisions for select to anon using(approved_at is not null and revoked_at is null);
create policy legal_revision_read on public.legal_revisions for select to authenticated using((select unseen_private.is_admin()) or (approved_at is not null and revoked_at is null));
create policy legal_revision_insert on public.legal_revisions for insert to authenticated with check((select unseen_private.is_admin()));
create policy legal_revision_update on public.legal_revisions for update to authenticated using((select unseen_private.is_admin())) with check((select unseen_private.is_admin()));
create policy legal_event_read on public.legal_events for select to authenticated using((select unseen_private.is_admin()));
create policy legal_event_insert on public.legal_events for insert to authenticated with check((select unseen_private.is_admin()) and actor_id=auth.uid());

create function unseen_private.valid_legal_text(value text,max_length integer,complete boolean) returns boolean
language plpgsql immutable set search_path='' as $$
declare item text[]; href text;
begin
 if value is null or char_length(value)>max_length or value~'[<>]' or value~'[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]' or (complete and nullif(btrim(value),'') is null) then return false;end if;
 for item in select regexp_matches(value,'\[[^\]\n]*\]\(([^)]*)\)','g') loop
  href:=item[1];
  if href~'[[:space:]\\<>]' or href~*'%(0[0-9a-f]|1[0-9a-f]|7f|5c|3c|3e)' then return false;end if;
  if href!~*'^https?://[^/@[:space:]]+([/:?#]|$)' and href!~*'^mailto:[^?[:space:]@]+@[^?[:space:]@]+\.[^?[:space:]@]+$' and href!~'^#[a-z][a-z0-9-]{0,63}$' and href!~'^/(privacy-policy|terms-of-service)(#[a-z][a-z0-9-]{0,63})?$' then return false;end if;
  if href~*'^https?://[^/]*@' then return false;end if;
 end loop;
 return true;
end $$;
create function unseen_private.valid_legal_content(value jsonb,complete boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare lang text; part jsonb; section jsonb; ids text[]; previous_ids text[]; label text;
begin
 if value is null or jsonb_typeof(value)<>'object' or octet_length(value::text)>262144 or value-array['en','ar-JO','review']<>'{}'::jsonb or not(value ?& array['en','ar-JO','review']) then return false;end if;
 if jsonb_typeof(value->'review')<>'object' or (value->'review')-array['operator','contact','retention','legalReview']<>'{}'::jsonb or not((value->'review') ?& array['operator','contact','retention','legalReview']) then return false;end if;
 foreach label in array array['operator','contact','retention','legalReview'] loop if jsonb_typeof(value->'review'->label)<>'boolean' then return false;end if;end loop;
 foreach lang in array array['en','ar-JO'] loop
  part:=value->lang;
  if jsonb_typeof(part)<>'object' or part-array['title','introduction','sections']<>'{}'::jsonb or not(part ?& array['title','introduction','sections']) then return false;end if;
  if jsonb_typeof(part->'title')<>'string' or jsonb_typeof(part->'introduction')<>'string' or not unseen_private.valid_legal_text(part->>'title',180,complete) or not unseen_private.valid_legal_text(part->>'introduction',3000,complete) then return false;end if;
  if jsonb_typeof(part->'sections')<>'array' or jsonb_array_length(part->'sections')>60 or (complete and jsonb_array_length(part->'sections')=0) then return false;end if;
  ids:=array[]::text[];
  for section in select x from jsonb_array_elements(part->'sections') x loop
   if jsonb_typeof(section)<>'object' or section-array['id','title','body']<>'{}'::jsonb or not(section ?& array['id','title','body']) then return false;end if;
   if jsonb_typeof(section->'id')<>'string' or section->>'id'!~'^[a-z][a-z0-9-]{0,63}$' or section->>'id'=any(array['legal-top','legal-document']) or section->>'id'=any(ids) then return false;end if;
   if jsonb_typeof(section->'title')<>'string' or jsonb_typeof(section->'body')<>'string' or not unseen_private.valid_legal_text(section->>'title',180,complete) or not unseen_private.valid_legal_text(section->>'body',24000,complete) then return false;end if;
   ids:=array_append(ids,section->>'id');
  end loop;
  if previous_ids is not null and ids is distinct from previous_ids then return false;end if;previous_ids:=ids;
  if complete and ((lang='en' and ((part->>'title')||(part->>'introduction'))!~'[A-Za-z]') or (lang='ar-JO' and ((part->>'title')||(part->>'introduction'))!~'[؀-ۿ]')) then return false;end if;
 end loop;
 return true;
exception when others then return false;
end $$;
alter table public.legal_revisions add constraint legal_content_safe check(unseen_private.valid_legal_content(content,false));
revoke all on function unseen_private.valid_legal_text(text,integer,boolean),unseen_private.valid_legal_content(jsonb,boolean) from public,anon,authenticated;
grant execute on function unseen_private.valid_legal_text(text,integer,boolean),unseen_private.valid_legal_content(jsonb,boolean) to authenticated;

