insert into public.legal_documents(document_key) values('privacy');
insert into public.legal_revisions(document_key,version,content) values('privacy',1,$legal_seed${"en":{"title":"Privacy Policy","introduction":"How Unseen Jo handles your account information, preferences, and discoveries.","sections":[{"id":"scope","title":"1. Scope and operator","body":"This policy explains how the current Unseen Jo website handles information when you explore Jordan, use recommendations, or manage an account. It covers the public website and its account features; independent services linked from the website have their own policies.\n\nUnseen Jo is the service name. A verified legal operator name, business address, and privacy contact have not yet been published for this version. The website owner still needs to confirm those details and the outstanding operating arrangements. Editorial publication approval does not itself certify legal compliance."},{"id":"account-data","title":"2. Registration, profiles, and authentication","body":"Registration asks for your full name, email address, and password. Supabase Auth receives the authentication details. Account records include an account identifier and authentication-related information. The application uses your name and preferred language to initialize your profile; you may edit your display name and language and optionally upload a profile image.\n\nProfile images are uploaded to the profile-avatars storage bucket. The application retrieves them using short-lived signed links rather than a permanent public profile-image URL. Do not upload identity documents or sensitive images.\n\nSign-in, email confirmation, password recovery, and email changes use Supabase Auth. Recovery uses a PKCE callback and may require the same browser profile and site address that initiated the request. Account emails necessarily pass your email address and the relevant authentication message to the configured delivery service. Which optional security notifications are enabled has not been verified."},{"id":"discoveries","title":"3. Saved places, preferences, and activity","body":"Signed-in account features store saved destination identifiers, travel preferences and interests, self-reported visited places with an optional visit date, and recommendation history containing destination identifiers and event times. These records support My Discoveries and personalized suggestions; a visit mark is not proof of your physical presence.\n\nGuest saves remain in browser storage. When you sign in, eligible guest saves may be merged into your account. Guest preferences may also be offered for saving to your account. Recommendation history records recommendations presented by the discovery flow; it is not a log of every page you view.\n\nSuggestions are calculated by application rules using inputs such as interests, budget, time, transport, group, and starting city. No external generative-AI recommendation service was identified in the current implementation."},{"id":"location","title":"4. Maps and optional location","body":"The Near You feature requests a single browser geolocation reading only when you choose that action and your browser permits it. Coordinates and reported accuracy are used in the current page to calculate approximate straight-line distances. This feature does not continuously track you or save that reading to your account database.\n\nYou may choose a city instead or decline location access. MapLibre displays map resources from OpenFreeMap, based on OpenStreetMap data. Loading map tiles, fonts, and related resources sends normal network information, such as your IP address and the requested map area, to their providers. Your browser or device location service has its own practices.\n\nOpening a Google Maps directions link takes you to Google’s service with the destination coordinates. Any location you then provide to that service is governed by its own settings and policy."},{"id":"purposes","title":"5. Purposes and lawful processing","body":"The application uses account information to authenticate you, maintain your profile, synchronize your chosen records, personalize suggestions, and send account-related messages. Technical requests also enable content delivery and access control. Authorized administrators manage tourism content and associated administrative audit records.\n\nWhere applicable, processing must meet Jordan’s Personal Data Protection Law No. 24 of 2023 and its relevant regulations and instructions. Required prior consent or another legally permitted basis must be established for the relevant processing. This draft does not establish that basis or certify compliance. Reading the policy or creating an account is not consent to unrelated optional processing.\n\nThe reviewed application contains no advertising-sale workflow, advertising pixels, or third-party audience analytics integration. This observation does not establish what operational logs or additional tools a hosting or delivery provider maintains."},{"id":"storage","title":"6. Cookies and browser storage","body":"The current app relies on localStorage and sessionStorage rather than an application-authored tracking-cookie system. Persistent storage holds the selected language, guest saved places, and Supabase sessions. User and administrator sessions use separate storage entries and refresh automatically; closing a tab does not necessarily sign you out.\n\nSession storage holds guest preferences, Explore state (including search filters and the map view), and email-resend cooldowns. The authentication library also stores temporary PKCE verification state in browser storage. Browser-only prototype saves may be retained for authorized preview use. No optional advertising-cookie consent manager is implemented.\n\nUse Sign out on shared devices. You may clear this site’s browser storage using browser settings; doing so can remove guest saves and preferences and disrupt a pending confirmation or recovery flow. It does not delete server-side account records. Third-party services may use their own cookies or storage under their policies."},{"id":"providers","title":"7. Providers, disclosure, and transfers","body":"Supabase provides authentication, the application database, and object storage. It receives the information required for those functions and associated network requests. Public destination media and branding can be served from public asset URLs; these are separate from private profile-image access.\n\nOpenFreeMap supplies map resources; Google Maps receives requests when you follow directions links. External destination or source websites receive information when you visit them. Website hosting and the underlying authentication email-delivery provider, their contractual arrangements, and their processing regions still require operator confirmation.\n\nAccount records are used through authenticated account features rather than a public user directory. The app includes access rules and administrator role checks; this is not a promise that no authorized provider or legally entitled authority can access data. Any additional disclosure must have a lawful basis and appropriate safeguards.\n\nRequests to these services may cross national borders. No Jordan-only storage guarantee is made. The operator must verify actual processing locations and any required safeguards and conditions for international transfers before public launch."},{"id":"retention","title":"8. Retention, deletion, and account controls","body":"The app stores account-linked records to make them available on subsequent visits. No automatic account expiry or verified fixed retention schedule is implemented. Operational logs, backups, and provider retention have not been verified; no immediate or complete backup-erasure promise is made. The prepared local fulfillment process is designed to remove the Auth account and dependent profile, preferences, saves, visits, recommendation history and feedback, after owned files are removed through Storage. It is not activated or fully integration-tested. Its design retains a minimal receipt without the account identifier. Public tourism content is preserved; editorial audit information and legally required records need separate review. Administrator accounts require a separate reviewed process.\n\nYou can edit supported profile fields, remove saved places and visit marks, and clear recommendation history using My Discoveries. These controls remove the selected application records; they do not delete your authentication account. Removing or replacing a profile image in your profile does not establish that every previously uploaded object has been erased.\n\nPrivacy & Account currently displays an availability notice. Data downloads and deletion requests are unavailable in production because the backend is not activated and deletion integration testing is incomplete. A prepared local implementation supports a scoped JSON export and a password-verified request, but it is not a live service. Its export excludes image binaries, passwords, tokens, provider logs and backups. Requests would require explicit confirmation and authorized manual processing after reviewed activation; submitting a request would not itself delete an account."},{"id":"security","title":"9. Security and your choices","body":"The implementation uses Supabase authentication, account-scoped queries, database row-level security rules in the project migrations, and server/database administrator authorization checks. Profile-image access uses signed links. These measures reduce exposure but do not establish an independent security audit or guarantee that unauthorized access, loss, or interruption cannot occur.\n\nChoose a strong unique password, protect your email account, keep recovery links private, and sign out on shared devices. Do not send passwords, session tokens, or recovery links in a privacy request. You can browse public destinations without an account and decline browser location access."},{"id":"rights","title":"10. Rights and privacy requests","body":"Depending on applicable law and its conditions, you may have rights to access and obtain a copy of your data, correct it, object to certain processing, withdraw prior consent, request erasure or restriction, and complain to the competent authority. Withdrawal does not itself undo earlier lawful processing. Rights and exceptions must be assessed under the applicable law, rather than treated as unconditional promises.\n\nPrivacy & Account shows the current availability notice; the prepared download and deletion-request tools are not active in production. Accounts without a password or using MFA would need a separately verified identity process that is not yet available here. Broader rights requests, a verified contact, monitored handling and legally reviewed timelines remain launch requirements. The Ministry of Digital Economy and Entrepreneurship publishes guidance and rights-request materials."},{"id":"children","title":"11. Children’s privacy","body":"The account experience is not designed specifically for children. This version has no age-verification or parental-consent workflow. Please do not submit a child’s personal information or create an account for a child without a lawful basis and any legally required guardian involvement. The operator must resolve eligibility and children’s-data handling before public launch."},{"id":"updates","title":"12. Updates and contact","body":"The revision date at the top identifies this version. Changes to features or providers should be reflected in an updated policy, with any notice or consent required by applicable law. This policy is not a substitute for required consent or operational safeguards.\n\nNo verified Unseen Jo legal or privacy contact is currently published in this version. Do not send sensitive information to an assumed email address or to an unrelated third party. Verified operator and contact details must be added before public launch."}]},"ar-JO":{"title":"سياسة الخصوصية","introduction":"كيف يتعامل Unseen Jo مع معلومات حسابك وتفضيلاتك واكتشافاتك.","sections":[{"id":"scope","title":"١. النطاق والجهة المشغّلة","body":"توضّح هذه السياسة كيفية تعامل موقع Unseen Jo بصورته الحالية مع المعلومات عند استكشاف الأردن أو استخدام الاقتراحات أو إدارة الحساب. وتشمل الموقع العام وخصائص الحساب، أما الخدمات المستقلة المرتبطة بالموقع فتخضع لسياساتها الخاصة.\n\nUnseen Jo هو اسم الخدمة. لم تُنشر لهذه النسخة بعد هوية قانونية معتمدة للمشغّل أو عنوان عمل أو وسيلة تواصل لشؤون الخصوصية. وما زال على مالك الموقع تأكيد هذه البيانات وترتيبات التشغيل غير المكتملة. ولا يُعدّ الاعتماد التحريري للنشر بحد ذاته شهادة بالامتثال القانوني."},{"id":"account-data","title":"٢. التسجيل والملف الشخصي والمصادقة","body":"يطلب التسجيل الاسم الكامل والبريد الإلكتروني وكلمة المرور. وتتلقى خدمة Supabase Auth بيانات المصادقة. وتشمل سجلات الحساب معرّفًا للحساب ومعلومات مرتبطة بالمصادقة. ويستخدم التطبيق الاسم واللغة المفضّلة لإنشاء الملف الشخصي، ويمكنك تعديل اسم العرض واللغة وإضافة صورة شخصية اختياريًا.\n\nتُرفع الصور الشخصية إلى حاوية التخزين profile-avatars، ويسترجعها التطبيق بروابط موقّعة قصيرة الصلاحية بدلًا من رابط عام دائم للصورة. يُرجى عدم رفع وثائق الهوية أو الصور الحساسة.\n\nتستخدم عمليات تسجيل الدخول وتأكيد البريد واستعادة كلمة المرور وتغيير البريد خدمة Supabase Auth. وتعتمد الاستعادة على مسار عودة يستخدم PKCE، وقد تتطلب ملف المتصفح نفسه وعنوان الموقع نفسه اللذين بدأ منهما الطلب. وتمرّ رسائل الحساب بعنوان بريدك ومحتوى رسالة المصادقة ذات الصلة عبر خدمة الإرسال المُعدّة. ولم يُتحقق من تفعيل إشعارات الأمان الاختيارية."},{"id":"discoveries","title":"٣. الأماكن المحفوظة والتفضيلات والنشاط","body":"تخزّن خصائص الحساب للمستخدم المسجّل معرّفات الوجهات المحفوظة وتفضيلات السفر والاهتمامات والأماكن التي يذكر أنه زارها مع تاريخ زيارة اختياري، وسجلًا للاقتراحات يضم معرّفات الوجهات وأوقات الأحداث. وتدعم هذه السجلات «اكتشافاتي» والاقتراحات الشخصية، ولا يُعدّ تسجيل الزيارة إثباتًا على الوجود الفعلي في المكان.\n\nتبقى محفوظات الزائر في تخزين المتصفح. وعند تسجيل الدخول، قد تُدمج الأماكن المؤهلة في الحساب، وقد يُعرض أيضًا حفظ تفضيلات الزائر فيه. ويسجّل سجل الاقتراحات ما يعرضه مسار الاكتشاف، ولا يسجّل كل صفحة تطّلع عليها.\n\nتُحسب الاقتراحات بقواعد داخل التطبيق اعتمادًا على مدخلات مثل الاهتمامات والميزانية والوقت ووسيلة النقل والمجموعة ومدينة الانطلاق. ولم يُعثر في التنفيذ الحالي على خدمة خارجية للذكاء الاصطناعي التوليدي لإنتاج الاقتراحات."},{"id":"location","title":"٤. الخرائط والموقع الاختياري","body":"تطلب خاصية «بالقرب منك» قراءة واحدة للموقع من المتصفح عندما تختار استخدامها ويسمح المتصفح بذلك. وتُستخدم الإحداثيات والدقة المُبلّغ عنها في الصفحة الحالية لحساب مسافات تقريبية بخط مستقيم. ولا تتتبّع هذه الخاصية تحرّكاتك باستمرار ولا تحفظ هذه القراءة في قاعدة بيانات حسابك.\n\nيمكنك اختيار مدينة بدلًا من ذلك أو رفض إذن الموقع. وتعرض مكتبة MapLibre موارد خرائط من OpenFreeMap تستند إلى بيانات OpenStreetMap. ويؤدي تحميل مربعات الخريطة والخطوط والموارد المرتبطة إلى إرسال معلومات الشبكة المعتادة، مثل عنوان الإنترنت والمنطقة المطلوبة من الخريطة، إلى مزوّديها. كما تخضع خدمة تحديد الموقع في متصفحك أو جهازك لممارساتها الخاصة.\n\nينقلك رابط الاتجاهات في Google Maps إلى خدمة Google مع إحداثيات الوجهة. وأي موقع تقدّمه بعد ذلك لتلك الخدمة يخضع لإعداداتها وسياستها."},{"id":"purposes","title":"٥. الأغراض ومشروعية المعالجة","body":"يستخدم التطبيق معلومات الحساب للمصادقة وإدارة الملف الشخصي ومزامنة السجلات التي تختارها وتخصيص الاقتراحات وإرسال رسائل الحساب. وتتيح الطلبات التقنية أيضًا عرض المحتوى وضبط الوصول. ويدير المسؤولون المخوّلون المحتوى السياحي وسجلات التدقيق الإدارية المرتبطة به.\n\nحيثما انطبق، يجب أن تستوفي المعالجة قانون حماية البيانات الشخصية الأردني رقم ٢٤ لسنة ٢٠٢٣ والأنظمة والتعليمات ذات الصلة. ويلزم تحديد الموافقة المسبقة المطلوبة أو أساس آخر تجيزه أحكام القانون لكل معالجة معنية. ولا تثبت هذه المسودة ذلك الأساس ولا تشهد بالامتثال. ولا يُعدّ الاطلاع على السياسة أو إنشاء حساب موافقة على معالجة اختيارية غير مرتبطة بالخدمة.\n\nلا يتضمن التطبيق الذي جرت مراجعته مسارًا لبيع البيانات لأغراض الإعلان أو بكسلات إعلانية أو تكاملًا خارجيًا لتحليلات الجمهور. ولا يثبت هذا الوصف طبيعة السجلات التشغيلية أو الأدوات الإضافية التي قد يحتفظ بها مزوّد الاستضافة أو الإرسال."},{"id":"storage","title":"٦. ملفات الارتباط وتخزين المتصفح","body":"يعتمد التطبيق الحالي على localStorage وsessionStorage بدلًا من نظام لملفات ارتباط التتبّع ينشئه التطبيق. ويحتفظ التخزين الدائم باللغة المختارة والأماكن المحفوظة للزائر وجلسات Supabase. وتُحفظ جلسات المستخدم والمسؤول في مفاتيح منفصلة وتتجدّد تلقائيًا؛ لذا لا يعني إغلاق علامة التبويب بالضرورة تسجيل الخروج.\n\nيحتفظ تخزين الجلسة بتفضيلات الزائر وحالة الاستكشاف، بما فيها مرشّحات البحث وعرض الخريطة، وفترات انتظار إعادة إرسال البريد. وتحتفظ مكتبة المصادقة أيضًا بحالة التحقق المؤقتة الخاصة بمسار PKCE في تخزين المتصفح. وقد تبقى محفوظات النماذج التجريبية داخل المتصفح لاستخدام المعاينة المخوّل. ولا يتضمن التطبيق أداة موافقة لملفات ارتباط إعلانية اختيارية.\n\nاستخدم تسجيل الخروج على الأجهزة المشتركة. ويمكنك مسح تخزين هذا الموقع من إعدادات المتصفح، وقد يؤدي ذلك إلى فقدان محفوظات الزائر وتفضيلاته وتعطيل عملية تأكيد أو استعادة قيد التنفيذ. ولا يحذف ذلك سجلات الحساب على الخادم. وقد تستخدم الخدمات الخارجية ملفات ارتباط أو تخزينًا خاصًا بها وفق سياساتها."},{"id":"providers","title":"٧. مزوّدو الخدمات والإفصاح ونقل البيانات","body":"توفّر Supabase المصادقة وقاعدة بيانات التطبيق وتخزين الملفات، وتتلقى المعلومات اللازمة لهذه الوظائف وطلبات الشبكة المرتبطة بها. وقد تُعرض صور الوجهات العامة ومواد الهوية البصرية عبر روابط أصول عامة، وهي منفصلة عن الوصول الخاص إلى الصور الشخصية.\n\nتوفّر OpenFreeMap موارد الخرائط، وتتلقى Google Maps الطلبات عند اتباع روابط الاتجاهات. وتتلقى مواقع الوجهات والمصادر الخارجية المعلومات عند زيارتها. وما زال يلزم أن يؤكد المشغّل مزوّد استضافة الموقع ومزوّد إرسال بريد المصادقة الفعلي وترتيباتهما التعاقدية ومناطق معالجة البيانات.\n\nتُستخدم سجلات الحساب عبر خصائص تتطلب المصادقة، ولا تُعرض في دليل عام للمستخدمين. ويتضمن التطبيق قواعد وصول وتحققًا من صلاحيات المسؤولين، لكن ذلك ليس تعهّدًا بمنع وصول كل مزوّد مخوّل أو جهة تملك حقًا قانونيًا. ويجب أن يستند أي إفصاح إضافي إلى أساس مشروع وضمانات مناسبة.\n\nقد تعبر الطلبات إلى هذه الخدمات حدود الدول. ولا نقدّم ضمانًا بقصر التخزين على الأردن. وعلى المشغّل التحقق من مواقع المعالجة الفعلية والضمانات والشروط اللازمة لنقل البيانات دوليًا قبل الإطلاق العام."},{"id":"retention","title":"٨. الاحتفاظ والحذف وأدوات الحساب","body":"يحتفظ التطبيق بالسجلات المرتبطة بالحساب لإتاحتها في الزيارات اللاحقة. ولا يتضمن انتهاءً تلقائيًا للحساب أو جدول احتفاظ ثابتًا جرى التحقق منه. ولم تُتحقق مدد الاحتفاظ بالسجلات التشغيلية والنسخ الاحتياطية لدى المزوّدين، ولا يوجد تعهّد بمحو النسخ الاحتياطية فورًا أو بالكامل. وقد صُممت عملية التنفيذ المحلية المُعدّة لإزالة حساب المصادقة والملف الشخصي والتفضيلات والمحفوظات والزيارات وسجل الاقتراحات والملاحظات، بعد إزالة الملفات المملوكة عبر خدمة التخزين، لكنها غير مفعّلة ولم يكتمل اختبار تكاملها. ويتضمن تصميمها الاحتفاظ بإيصال مقتضب دون معرّف الحساب. ويُحفظ المحتوى السياحي العام، فيما تحتاج معلومات التدقيق التحريري والسجلات التي يوجبها القانون إلى مراجعة مستقلة. وتتطلب حسابات المسؤولين إجراءً منفصلًا خاضعًا للمراجعة.\n\nيمكنك تعديل حقول الملف المدعومة وإزالة الأماكن المحفوظة وعلامات الزيارة ومسح سجل الاقتراحات من «اكتشافاتي». وتحذف هذه الأدوات سجلات التطبيق المختارة، ولا تحذف حساب المصادقة. كما أن إزالة الصورة الشخصية أو استبدالها في الملف لا تثبت محو كل ملف سبق رفعه.\n\nيعرض قسم الخصوصية والحساب حاليًا إشعارًا بعدم الإتاحة. تنزيل البيانات وطلبات الحذف غير متاحين في نسخة الإنتاج، لأن الخدمة الخلفية لم تُفعّل ولم يكتمل اختبار تكامل الحذف. وقد أُعدّ تنفيذ محلي لتصدير سجلات محددة بصيغة JSON وطلب موثّق بكلمة المرور، لكنه ليس خدمة عاملة. ويستثني التصدير محتوى الصور وكلمات المرور والرموز وسجلات المزوّدين ونسخهم الاحتياطية. وبعد تفعيل خاضع للمراجعة، ستتطلب الطلبات تأكيدًا صريحًا ومعالجة يدوية مخوّلة؛ ولن يؤدي تقديم الطلب وحده إلى حذف الحساب."},{"id":"security","title":"٩. الأمان والخيارات المتاحة لك","body":"يستخدم التنفيذ مصادقة Supabase واستعلامات مرتبطة بالحساب وقواعد أمان على مستوى الصفوف ضمن ملفات ترحيل قاعدة البيانات وفحوص صلاحيات المسؤول على الخادم أو قاعدة البيانات. ويستخدم الوصول إلى الصور الشخصية روابط موقّعة. وتحدّ هذه الإجراءات من الانكشاف، لكنها لا تثبت إجراء تدقيق أمني مستقل ولا تضمن استحالة الوصول غير المصرّح به أو الفقد أو الانقطاع.\n\nاختر كلمة مرور قوية وفريدة، واحمِ بريدك الإلكتروني، واحتفظ بروابط الاستعادة سرية، وسجّل الخروج على الأجهزة المشتركة. ولا ترسل كلمات المرور أو رموز الجلسات أو روابط الاستعادة ضمن طلب خصوصية. ويمكنك تصفّح الوجهات العامة دون حساب ورفض إذن الموقع في المتصفح."},{"id":"rights","title":"١٠. الحقوق وطلبات الخصوصية","body":"بحسب القانون الواجب التطبيق وشروطه، قد تكون لك حقوق في الاطلاع على بياناتك والحصول على نسخة منها وتصحيحها والاعتراض على بعض أوجه معالجتها وسحب الموافقة المسبقة وطلب المحو أو التقييد وتقديم شكوى إلى الجهة المختصة. ولا يُبطل سحب الموافقة بذاته المعالجة السابقة المشروعة. وتُقيّم الحقوق والاستثناءات وفق القانون الواجب التطبيق، ولا تُقدّم بوصفها وعودًا مطلقة.\n\nيعرض قسم الخصوصية والحساب إشعار الإتاحة الحالي؛ وأدوات التنزيل وطلب الحذف المُعدّة غير مفعّلة في نسخة الإنتاج. وتحتاج الحسابات دون كلمة مرور أو المزودة بمصادقة متعددة العوامل إلى إجراء مستقل للتحقق من الهوية لم يتوفر هنا بعد. وتبقى الطلبات الأوسع وقناة التواصل المعتمدة والمتابعة ومهل الاستجابة المراجعة قانونيًا من متطلبات الإطلاق. وتنشر وزارة الاقتصاد الرقمي والريادة إرشادات ومواد لطلبات الحقوق."},{"id":"children","title":"١١. خصوصية الأطفال","body":"لم تُصمّم تجربة الحساب خصيصًا للأطفال. ولا تتضمن هذه النسخة مسارًا للتحقق من العمر أو موافقة ولي الأمر. يُرجى عدم تقديم بيانات طفل أو إنشاء حساب له دون أساس مشروع ومشاركة ولي الأمر حيث يقتضي القانون ذلك. وعلى المشغّل حسم الأهلية وآلية التعامل مع بيانات الأطفال قبل الإطلاق العام."},{"id":"updates","title":"١٢. التحديثات والتواصل","body":"يشير تاريخ المراجعة أعلى الصفحة إلى هذه النسخة. وينبغي أن تنعكس تغييرات الخصائص أو المزوّدين في سياسة محدّثة، مع أي إشعار أو موافقة يقتضيهما القانون. ولا تحل هذه السياسة محل الموافقة المطلوبة أو الضمانات التشغيلية.\n\nلم تُنشر في هذه النسخة وسيلة تواصل معتمدة مع Unseen Jo للشؤون القانونية أو الخصوصية. لا ترسل معلومات حساسة إلى عنوان بريد مفترض أو طرف غير معني. ويلزم إضافة بيانات المشغّل والتواصل المعتمدة قبل الإطلاق العام."}]},"review":{"operator":false,"contact":false,"retention":false,"legalReview":false}}$legal_seed$::jsonb);
insert into public.legal_documents(document_key) values('terms');
insert into public.legal_revisions(document_key,version,content) values('terms',1,$legal_seed${"en":{"title":"Terms of Service","introduction":"The conditions for using Unseen Jo to explore Jordan and plan your discoveries.","sections":[{"id":"acceptance","title":"1. About these terms","body":"These terms describe the conditions for using Unseen Jo, a tourism discovery and recommendation website focused on Jordan. Read them together with the Privacy Policy before registering. If you cannot accept the applicable conditions, do not create an account or use account features. Mandatory rights under applicable law remain unaffected.\n\nThese are review drafts, not a representation that launch requirements are complete. Unseen Jo is the service name; a verified legal operator identity, business address, and legal contact have not yet been published. Those details and the effective launch terms must be confirmed before public launch."},{"id":"service","title":"2. What the service provides","body":"Unseen Jo lets you explore destination information and maps, set travel preferences, receive rule-based suggestions through Surprise Me, and maintain saved places, self-reported visits, and recommendation history. Public browsing is available without an account; synchronized personal records require sign-in.\n\nUnseen Jo does not currently provide bookings, ticket sales, payment processing, travel-agency services, or a contract with a destination operator. Saving a place or receiving a recommendation does not reserve entry, transport, accommodation, or any other service."},{"id":"eligibility","title":"3. Eligibility and registration","body":"Use account features only if you have the legal capacity and any permissions required under applicable law. Do not register on behalf of another person without authority. This version does not verify age or provide a parental-consent process; it should not be treated as a child-account service.\n\nProvide accurate registration information that you are entitled to use, maintain access to your email address, and keep your profile reasonably current. Email confirmation may be required by the authentication configuration. Administrator privileges require separately authorized roles; registering or visiting an administrator URL does not grant them."},{"id":"security","title":"4. Account responsibility and security","body":"Keep your password and recovery links confidential. Do not share a session or impersonate another user. Sign out on shared devices; sessions can persist after you close the browser. Recovery and confirmation links can expire and may require the same browser profile and site address used for the request.\n\nIf you suspect unauthorized use, use the supported password-recovery and sign-out controls and secure your email account. A verified support contact remains to be published; do not send passwords or authentication tokens to an assumed contact. You are not automatically responsible for activity beyond your control where applicable law provides otherwise."},{"id":"use","title":"5. Permitted and prohibited use","body":"Use the service for lawful destination discovery and personal travel planning. Respect local law, site rules, protected areas, private property, and the rights of other people. Obtain any permits and independent advice needed for your trip.\n\nDo not attempt unauthorized access, bypass account or administrator restrictions, extract private records, upload malicious files, disrupt availability, impersonate others, or use the service for fraud or unlawful activity. Do not copy or redistribute protected content beyond permission or applicable legal exceptions. Automated access must respect technical limits and must not impair the service or others’ rights."},{"id":"content","title":"6. Your information and uploaded images","body":"The current service supports profile names, optional profile images, preferences, and private personal destination records. It does not provide a public user-review, comment, or destination-submission feature. Administrative content editing is limited to authorized administrators.\n\nYou retain any rights you hold in material you provide. By uploading a profile image, you permit the storage, processing, and display needed for the profile feature, subject to the Privacy Policy and applicable law; this is not a transfer of ownership or permission for unrelated advertising. Upload only material you have the right to use and avoid sensitive or unlawful content."},{"id":"ip","title":"7. Brand, destination images, and third-party rights","body":"The Unseen Jo name, logo, interface, software, text, photographs, and map resources may be protected by intellectual-property rights. Rights can belong to the operator or to third-party owners; display on this site does not mean every asset is owned by Unseen Jo or available for reuse.\n\nRespect image credits, source notices, and applicable licenses, including map-data and style attributions. Public access to a destination image or branding file does not grant a blanket license to reproduce it. Nothing here restricts uses expressly permitted by applicable law."},{"id":"recommendations","title":"8. Personal records and recommendations","body":"Saved destinations and visited marks are personal planning aids. Guest saves depend on browser storage and may be lost when it is cleared. Signed-in records depend on successful synchronization. Self-reported visits are not verified travel records.\n\nRecommendations reflect selected inputs and the data available to the application; they are not professional travel advice, an assessment of your fitness, or a guarantee of suitability or safety. Prototype or preview content can contain synthetic planning values and should not be relied on as verified destination information."},{"id":"accuracy","title":"9. Tourism information and travel decisions","body":"Destination descriptions, coordinates, prices, opening hours, transport options, accessibility details, travel times, and budget estimates can be incomplete, approximate, outdated, or based on prototype data where indicated. Availability, weather, access restrictions, seasonal conditions, and local rules can change. Map pins may indicate an approximate area rather than an entrance.\n\nBefore travelling, verify essential details directly with the destination or an authoritative source, including current prices, permits, opening times, route conditions, and accessibility. Straight-line distances are not driving routes or travel-time guarantees. The platform is not an emergency, navigation-safety, or rescue service; use appropriate official channels when assistance is needed."},{"id":"external","title":"10. External services and links","body":"Authentication and storage use Supabase. Maps use MapLibre and resources from OpenFreeMap based on OpenStreetMap data. Directions and destination-source links can open independent websites such as Google Maps. Their terms, privacy practices, availability, and charges, if any, are their responsibility.\n\nA link or recommendation is not a guarantee, endorsement of every statement, or an agency relationship. Any arrangement you make with an independent operator is separate from this discovery service."},{"id":"availability","title":"11. Availability, changes, and account restrictions","body":"Features and destination content may change, and maintenance, provider failures, or network problems may interrupt access. Continuous availability, permanent storage, and error-free operation are not guaranteed. The operator should give any notice required by applicable law for material changes.\n\nAccess may be restricted where reasonably necessary to address unlawful use, security risks, or material breaches, subject to applicable law and fair process where required. No automated suspension or appeal workflow is represented as implemented. You may stop using the service and sign out; these actions do not erase your account. The Privacy Policy explains the supported deletion-request process and remaining contact and operational limitations."},{"id":"liability","title":"12. Warranties and responsibility","body":"To the extent permitted by applicable law, the service is provided as available without a promise that information is complete, current, or suitable for every journey. You remain responsible for checking travel conditions and making informed decisions. This does not excuse a failure to meet duties that the law makes mandatory.\n\nTo the extent permitted by applicable law, the operator is not responsible for losses caused solely by independent third-party services, conditions at destinations, or reliance on clearly identified estimates without reasonable verification. Responsibility must reflect the cause of the loss and the circumstances. No blanket exclusion, arbitrary monetary cap, or waiver of all liability is imposed here.\n\nNothing in these terms excludes liability or remedies that cannot lawfully be excluded, including protections concerning fraud, intentional wrongdoing, negligence, personal injury, or consumer rights to the extent applicable law makes those protections mandatory."},{"id":"law","title":"13. Applicable law and disputes","body":"Applicable mandatory law governs the service and any dispute. Relevant Jordanian law, including personal data protection requirements where applicable, must be considered for use in Jordan. The operator’s unconfirmed legal identity and establishment prevent this draft from specifying a verified contractual choice of law or exclusive court.\n\nNo mandatory arbitration, exclusive foreign venue, or waiver of access to a competent court is imposed. Any final governing-law and dispute provision must preserve non-waivable rights and be reviewed before public launch. A verified channel for raising issues with the operator remains to be published."},{"id":"updates","title":"14. Changes and contact","body":"The date at the top identifies this revision. Updated terms should be posted when the service materially changes, with notice and acceptance where legally required. This version does not record a separate terms-acceptance checkbox or a versioned acceptance record, and no such record is claimed.\n\nNo verified legal contact for Unseen Jo is published in this version. Operator identity, a usable contact channel, and final legal approval are outstanding launch requirements. Do not send sensitive information to an assumed address. Both language versions are intended to communicate the same meaning; neither removes rights protected by applicable law."}]},"ar-JO":{"title":"شروط الخدمة","introduction":"شروط استخدام Unseen Jo لاستكشاف الأردن والتخطيط لاكتشافاتك.","sections":[{"id":"acceptance","title":"١. حول هذه الشروط","body":"توضّح هذه الشروط أحكام استخدام Unseen Jo، وهو موقع لاكتشاف الوجهات السياحية واقتراحها في الأردن. يُرجى قراءتها مع سياسة الخصوصية قبل التسجيل. وإذا لم تستطع قبول الأحكام المنطبقة، فلا تنشئ حسابًا ولا تستخدم خصائصه. وتبقى الحقوق الآمرة المقررة في القانون محفوظة.\n\nهذه مسودات للمراجعة، ولا تعني استكمال متطلبات الإطلاق. Unseen Jo هو اسم الخدمة، ولم تُنشر بعد هوية قانونية معتمدة للمشغّل أو عنوان عمل أو وسيلة تواصل قانونية. ويلزم تأكيدها واعتماد شروط الإطلاق النافذة قبل الإطلاق العام."},{"id":"service","title":"٢. ما تقدّمه الخدمة","body":"يتيح Unseen Jo استكشاف معلومات الوجهات والخرائط وتحديد تفضيلات السفر وتلقي اقتراحات قائمة على قواعد عبر «فاجئني» وإدارة الأماكن المحفوظة والزيارات المصرّح بها ذاتيًا وسجل الاقتراحات. ويمكن التصفّح العام دون حساب، بينما تتطلب مزامنة السجلات الشخصية تسجيل الدخول.\n\nلا يوفّر Unseen Jo حاليًا الحجوزات أو بيع التذاكر أو معالجة المدفوعات أو خدمات وكالات السفر، ولا ينشئ عقدًا مع مشغّل الوجهة. ولا يُعدّ حفظ مكان أو تلقي اقتراح حجزًا للدخول أو النقل أو الإقامة أو أي خدمة أخرى."},{"id":"eligibility","title":"٣. الأهلية والتسجيل","body":"استخدم خصائص الحساب فقط إذا كانت لديك الأهلية القانونية والأذونات اللازمة وفق القانون الواجب التطبيق. ولا تسجّل نيابة عن شخص آخر دون تفويض. ولا تتحقق هذه النسخة من العمر ولا توفّر إجراءات لموافقة ولي الأمر، ولا ينبغي اعتبارها خدمة لحسابات الأطفال.\n\nقدّم بيانات تسجيل صحيحة يحق لك استخدامها، وحافظ على إمكانية الوصول إلى بريدك الإلكتروني وحدّث ملفك بصورة معقولة. وقد تتطلب إعدادات المصادقة تأكيد البريد. وتتطلب صلاحيات المسؤول أدوارًا مخوّلة على نحو مستقل؛ ولا يمنحها التسجيل أو فتح رابط الإدارة."},{"id":"security","title":"٤. مسؤولية الحساب وأمانه","body":"حافظ على سرية كلمة المرور وروابط الاستعادة. ولا تشارك جلسة الدخول أو تنتحل هوية مستخدم آخر. وسجّل الخروج على الأجهزة المشتركة، إذ قد تستمر الجلسة بعد إغلاق المتصفح. وقد تنتهي صلاحية روابط الاستعادة والتأكيد أو تتطلب ملف المتصفح وعنوان الموقع نفسيهما المستخدمين عند الطلب.\n\nإذا اشتبهت في استخدام غير مصرّح به، فاستخدم أدوات استعادة كلمة المرور وتسجيل الخروج المدعومة وأمّن بريدك الإلكتروني. ولم تُنشر بعد وسيلة دعم معتمدة؛ فلا ترسل كلمات المرور أو رموز المصادقة إلى جهة مفترضة. ولا تتحمل تلقائيًا مسؤولية نشاط خارج سيطرتك حيث يقرر القانون خلاف ذلك."},{"id":"use","title":"٥. الاستخدام المسموح والمحظور","body":"استخدم الخدمة بصورة مشروعة لاكتشاف الوجهات والتخطيط الشخصي للسفر. واحترم القانون المحلي وقواعد المواقع والمناطق المحمية والملكية الخاصة وحقوق الآخرين. واحصل على التصاريح والمشورة المستقلة اللازمة لرحلتك.\n\nيُحظر محاولة الوصول غير المصرّح به أو تجاوز قيود الحساب والإدارة أو استخراج السجلات الخاصة أو رفع ملفات ضارة أو تعطيل الخدمة أو انتحال الهوية أو استخدامها للاحتيال أو نشاط غير مشروع. ولا تنسخ المحتوى المحمي أو تعيد توزيعه خارج نطاق الإذن أو الاستثناءات القانونية. ويجب أن يحترم الوصول الآلي الحدود التقنية وألا يضرّ بالخدمة أو بحقوق الآخرين."},{"id":"content","title":"٦. معلوماتك والصور التي ترفعها","body":"تدعم الخدمة الحالية أسماء الملفات الشخصية والصور الشخصية الاختيارية والتفضيلات وسجلات الوجهات الشخصية الخاصة. ولا توفّر خاصية عامة لمراجعات المستخدمين أو تعليقاتهم أو اقتراح وجهات للنشر. ويقتصر تحرير المحتوى الإداري على المسؤولين المخوّلين.\n\nتحتفظ بما تملكه من حقوق في المواد التي تقدّمها. وبرفع صورة شخصية، تسمح بالتخزين والمعالجة والعرض اللازم لخاصية الملف الشخصي، مع مراعاة سياسة الخصوصية والقانون. ولا ينقل ذلك الملكية ولا يمنح إذنًا بإعلانات غير مرتبطة. ولا ترفع إلا ما يحق لك استخدامه، وتجنّب المحتوى الحساس أو غير المشروع."},{"id":"ip","title":"٧. الهوية البصرية وصور الوجهات وحقوق الغير","body":"قد يخضع اسم Unseen Jo وشعاره وواجهته وبرمجياته ونصوصه وصوره وموارد خرائطه لحقوق الملكية الفكرية. وقد تعود الحقوق للمشغّل أو لمالكين آخرين؛ ولا يعني عرض أصل على الموقع أن Unseen Jo يملكه أو أنه متاح لإعادة الاستخدام.\n\nاحترم نسب الصور وإشعارات المصادر والتراخيص المنطبقة، بما فيها نسب بيانات الخرائط وتصاميمها. ولا يتيح الوصول العام إلى صورة وجهة أو ملف هوية بصرية ترخيصًا شاملًا لنسخه. ولا تقيّد هذه الشروط الاستخدامات التي يجيزها القانون صراحة."},{"id":"recommendations","title":"٨. السجلات الشخصية والاقتراحات","body":"الأماكن المحفوظة وعلامات الزيارة أدوات للتخطيط الشخصي. وتعتمد محفوظات الزائر على تخزين المتصفح وقد تضيع عند مسحه. وتعتمد سجلات الحساب على نجاح المزامنة. والزيارات المصرّح بها ذاتيًا ليست سجل سفر موثّقًا.\n\nتعكس الاقتراحات المدخلات المختارة والبيانات المتاحة للتطبيق؛ وليست مشورة سفر مهنية أو تقييمًا لقدرتك البدنية أو ضمانًا للملاءمة أو السلامة. وقد يحتوي المحتوى التجريبي أو المعاينات على قيم تخطيطية اصطناعية، ولا ينبغي الاعتماد عليها بوصفها معلومات وجهة متحققة."},{"id":"accuracy","title":"٩. المعلومات السياحية وقرارات السفر","body":"قد تكون أوصاف الوجهات والإحداثيات والأسعار وساعات العمل وخيارات النقل وإمكانية الوصول وأوقات الرحلات وتقديرات الميزانية ناقصة أو تقريبية أو قديمة، أو قائمة على بيانات تجريبية حيث يُشار إلى ذلك. وقد تتغير الإتاحة والطقس وقيود الدخول والظروف الموسمية والقواعد المحلية. وقد تشير علامة الخريطة إلى منطقة تقريبية بدلًا من مدخل محدد.\n\nتحقّق قبل السفر من التفاصيل الأساسية لدى الوجهة مباشرة أو من مصدر مختص، بما يشمل الأسعار والتصاريح وساعات العمل وحالة الطريق وإمكانية الوصول. والمسافات بخط مستقيم ليست طرق قيادة أو ضمانًا لمدة الرحلة. وليست المنصة خدمة طوارئ أو لضمان سلامة الملاحة أو للإنقاذ؛ فاستخدم القنوات الرسمية المناسبة عند الحاجة للمساعدة."},{"id":"external","title":"١٠. الخدمات والروابط الخارجية","body":"تستخدم المصادقة والتخزين Supabase. وتستخدم الخرائط MapLibre وموارد من OpenFreeMap تستند إلى بيانات OpenStreetMap. وقد تفتح روابط الاتجاهات ومصادر الوجهات مواقع مستقلة مثل Google Maps. وتعود مسؤولية شروط هذه الخدمات وممارسات خصوصيتها وإتاحتها ورسومها، إن وجدت، إلى الجهات المعنية بها.\n\nلا يُعدّ الرابط أو الاقتراح ضمانًا أو تأييدًا لكل عبارة أو إنشاءً لعلاقة وكالة. وأي ترتيب تجريه مع مشغّل مستقل منفصل عن خدمة الاكتشاف هذه."},{"id":"availability","title":"١١. الإتاحة والتغييرات وقيود الحساب","body":"قد تتغير الخصائص ومحتوى الوجهات، وقد تتسبب الصيانة أو أعطال المزوّدين أو مشكلات الشبكة في انقطاع الوصول. ولا تُضمن الإتاحة المستمرة أو التخزين الدائم أو التشغيل الخالي من الأخطاء. وينبغي أن يقدّم المشغّل أي إشعار يوجبه القانون عند التغييرات الجوهرية.\n\nقد يُقيّد الوصول بالقدر المعقول اللازم لمواجهة الاستخدام غير المشروع أو مخاطر الأمان أو المخالفات الجوهرية، مع مراعاة القانون والإجراءات المنصفة حيث تكون مطلوبة. ولا ندّعي تنفيذ إجراءات مؤتمتة للإيقاف أو التظلّم. ويمكنك التوقف عن الاستخدام وتسجيل الخروج، لكن ذلك لا يمحو الحساب. وتوضّح سياسة الخصوصية إجراءات طلب الحذف المدعومة وحدود التواصل والتشغيل المتبقية."},{"id":"liability","title":"١٢. الضمانات والمسؤولية","body":"في الحدود التي يجيزها القانون، تُقدّم الخدمة بحسب إتاحتها دون تعهّد باكتمال المعلومات أو حداثتها أو ملاءمتها لكل رحلة. وتبقى مسؤولًا عن التحقق من ظروف السفر واتخاذ قرارات واعية. ولا يعفي ذلك من واجبات يفرضها القانون على نحو ملزم.\n\nفي الحدود التي يجيزها القانون، لا يتحمل المشغّل مسؤولية خسائر تنشأ حصرًا عن خدمات مستقلة للغير أو ظروف الوجهات أو الاعتماد على تقديرات مبيّنة بوضوح دون تحقق معقول. ويجب أن تتناسب المسؤولية مع سبب الضرر وظروفه. ولا تفرض هذه الشروط استبعادًا شاملًا للمسؤولية أو سقفًا ماليًا اعتباطيًا أو تنازلًا عن المسؤولية بجميع صورها.\n\nلا تستبعد هذه الشروط مسؤولية أو وسائل انتصاف لا يجوز استبعادها قانونًا، بما فيها الحماية المتعلقة بالاحتيال أو الفعل العمدي أو الإهمال أو الإصابة الشخصية أو حقوق المستهلك، بالقدر الذي يجعل فيه القانون تلك الحماية ملزمة."},{"id":"law","title":"١٣. القانون الواجب التطبيق والمنازعات","body":"تحكم القواعد القانونية الآمرة الواجبة التطبيق الخدمة وأي نزاع يتعلق بها. ويجب مراعاة القانون الأردني ذي الصلة عند الاستخدام في الأردن، بما يشمل متطلبات حماية البيانات حيثما انطبقت. ولعدم تأكيد هوية المشغّل القانونية ومقرّه، لا تحدد هذه المسودة اختيارًا تعاقديًا متحققًا للقانون أو محكمة حصرية.\n\nلا تفرض هذه الشروط تحكيمًا إلزاميًا أو جهة تقاضٍ أجنبية حصرية أو تنازلًا عن اللجوء إلى المحكمة المختصة. ويجب أن يحفظ أي نص نهائي للقانون وتسوية المنازعات الحقوق غير القابلة للتنازل وأن يخضع للمراجعة قبل الإطلاق العام. ولم تُنشر بعد قناة معتمدة لطرح المسائل على المشغّل."},{"id":"updates","title":"١٤. التعديلات والتواصل","body":"يشير التاريخ أعلى الصفحة إلى هذه المراجعة. وينبغي نشر شروط محدّثة عند تغيير الخدمة جوهريًا، مع الإشعار والقبول حيث يقتضيهما القانون. ولا تسجّل هذه النسخة خانة مستقلة لقبول الشروط أو سجل قبول مرتبطًا برقم إصدار، ولا ندّعي وجود مثل هذا السجل.\n\nلم تُنشر في هذه النسخة وسيلة تواصل قانونية معتمدة مع Unseen Jo. وتظل هوية المشغّل وقناة التواصل القابلة للاستخدام والاعتماد القانوني النهائي من متطلبات الإطلاق غير المكتملة. ولا ترسل معلومات حساسة إلى عنوان مفترض. ويُقصد بالنسختين اللغويتين نقل المعنى نفسه، ولا تنتقص أي منهما من الحقوق التي يحميها القانون الواجب التطبيق."}]},"review":{"operator":false,"contact":false,"retention":false,"legalReview":false}}$legal_seed$::jsonb);
-- END_INITIAL_REVIEW_DRAFTS

create function unseen_private.guard_legal_write() returns trigger
language plpgsql security invoker set search_path='' as $$
declare target text; action text; old_json jsonb; new_json jsonb;
begin
 if tg_op='DELETE' then raise insufficient_privilege using message='Legal history cannot be deleted';end if;
 -- Preserve Auth's existing ON DELETE SET NULL behavior for an actor who was
 -- subsequently removed by a separately authorized account process. Content,
 -- approval and audit facts remain immutable. A live actor cannot be erased.
 if tg_op='UPDATE' and tg_table_name='legal_documents' and pg_trigger_depth()>1 then
  if old.last_editor is not null and new.last_editor is null and (to_jsonb(old)-'last_editor')=(to_jsonb(new)-'last_editor') then
   if not exists(select 1 from auth.users where id=old.last_editor) then return new;end if;
  end if;
 elsif tg_op='UPDATE' and tg_table_name='legal_events' and pg_trigger_depth()>1 then
  if old.actor_id is not null and new.actor_id is null and (to_jsonb(old)-'actor_id')=(to_jsonb(new)-'actor_id') then
   if not exists(select 1 from auth.users where id=old.actor_id) then return new;end if;
  end if;
 end if;
 target:=new.document_key;action:=split_part(coalesce(current_setting('unseen.legal_write',true),''),':',2);
 if not unseen_private.is_admin() or current_setting('unseen.legal_write',true) is distinct from target||':'||coalesce(action,'') or action not in ('save','publish','revoke','restore') then raise insufficient_privilege using message='Use the authorized legal management operation';end if;
 if tg_table_name='legal_documents' then
  if tg_op<>'UPDATE' or new.document_key<>old.document_key or new.lock_version<>old.lock_version+1 or new.revision_count<>old.revision_count+(case when action in ('save','restore') then 1 else 0 end) then raise check_violation using message='Invalid legal document version';end if;
  new.updated_at:=clock_timestamp();new.last_editor:=case when action in ('save','restore') then auth.uid() else old.last_editor end;
 elsif tg_table_name='legal_revisions' then
  if tg_op='INSERT' then
   if action not in ('save','restore') or new.version<>(select revision_count+1 from public.legal_documents where document_key=target) or new.approved_at is not null or new.revoked_at is not null then raise check_violation using message='A new revision must be an unapproved draft';end if;
   new.created_at:=clock_timestamp();
  else
   old_json:=to_jsonb(old)-array['approved_at','revoked_at'];new_json:=to_jsonb(new)-array['approved_at','revoked_at'];
   if old_json is distinct from new_json then raise check_violation using message='Saved legal content is immutable; save a new draft';end if;
   if action='publish' and old.approved_at is null and old.revoked_at is null and new.approved_at is not null and new.revoked_at is null and new.version=(select revision_count from public.legal_documents where document_key=target) and unseen_private.valid_legal_content(new.content,true) then new.approved_at:=clock_timestamp();
   elsif action='revoke' and old.approved_at is not null and old.revoked_at is null and new.approved_at is not distinct from old.approved_at and new.revoked_at is not null then new.revoked_at:=clock_timestamp();
   else raise check_violation using message='Invalid legal approval transition';end if;
  end if;
 else
  if tg_op<>'INSERT' or new.action<>action then raise insufficient_privilege using message='Legal approval history is append-only';end if;
  new.actor_id:=auth.uid();new.created_at:=clock_timestamp();
 end if;
 return new;
end $$;
revoke all on function unseen_private.guard_legal_write() from public,anon,authenticated;
create trigger legal_head_guard before insert or update or delete on public.legal_documents for each row execute function unseen_private.guard_legal_write();
create trigger legal_revision_guard before insert or update or delete on public.legal_revisions for each row execute function unseen_private.guard_legal_write();
create trigger legal_event_guard before insert or update or delete on public.legal_events for each row execute function unseen_private.guard_legal_write();

create function unseen_private.change_legal_document(target text,expected_lock bigint,operation text,changes jsonb default null,revision_id uuid default null) returns uuid
language plpgsql security invoker set search_path='' as $$
declare head public.legal_documents; revision public.legal_revisions; selected uuid; previous_context text;
begin
 if not unseen_private.is_admin() then raise insufficient_privilege using message='Administrator session required';end if;
 if operation not in ('save','publish','revoke','restore') then raise check_violation using message='Invalid legal operation';end if;
 select * into head from public.legal_documents where document_key=target for update;
 if not found then raise no_data_found using message='Legal document unavailable';end if;
 if expected_lock is null or head.lock_version<>expected_lock then raise serialization_failure using message='Legal document changed. Reload before saving';end if;
 if operation='save' then
  if not unseen_private.valid_legal_content(changes,false) then raise check_violation using message='Unsafe or invalid bilingual legal content';end if;
  select * into revision from public.legal_revisions where document_key=target and version=head.revision_count;
  if revision.approved_at is null and revision.content=changes then return revision.id;end if;
 else
  select * into revision from public.legal_revisions where document_key=target and id=revision_id;
  if not found then raise no_data_found using message='Legal revision unavailable';end if;
  if operation='publish' and (revision.version<>head.revision_count or revision.approved_at is not null or not unseen_private.valid_legal_content(revision.content,true)) then raise check_violation using message='Publish the latest complete saved bilingual draft';end if;
  if operation='revoke' and (revision.approved_at is null or revision.revoked_at is not null) then raise check_violation using message='Only an approved revision can be revoked';end if;
 end if;
 previous_context:=current_setting('unseen.legal_write',true);perform set_config('unseen.legal_write',target||':'||operation,true);
 if operation in ('save','restore') then
  insert into public.legal_revisions(document_key,version,content) values(target,head.revision_count+1,case when operation='save' then changes else revision.content end) returning id into selected;
 else
  selected:=revision.id;
  if operation='publish' then update public.legal_revisions set approved_at=clock_timestamp() where id=selected;
  else update public.legal_revisions set revoked_at=clock_timestamp() where id=selected;end if;
 end if;
 update public.legal_documents set lock_version=lock_version+1,revision_count=revision_count+case when operation in ('save','restore') then 1 else 0 end where document_key=target;
 insert into public.legal_events(document_key,revision_id,action,actor_id) values(target,selected,operation,auth.uid());
 perform set_config('unseen.legal_write',coalesce(previous_context,''),true);
 return selected;
end $$;
revoke all on function unseen_private.change_legal_document(text,bigint,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function unseen_private.change_legal_document(text,bigint,text,jsonb,uuid) to authenticated;
create function public.admin_save_legal_draft(target text,expected_lock bigint,changes jsonb) returns uuid language sql security invoker set search_path='' as $$select unseen_private.change_legal_document(target,expected_lock,'save',changes,null)$$;
create function public.admin_publish_legal(target text,expected_lock bigint,revision_id uuid) returns uuid language sql security invoker set search_path='' as $$select unseen_private.change_legal_document(target,expected_lock,'publish',null,revision_id)$$;
create function public.admin_revoke_legal(target text,expected_lock bigint,revision_id uuid) returns uuid language sql security invoker set search_path='' as $$select unseen_private.change_legal_document(target,expected_lock,'revoke',null,revision_id)$$;
create function public.admin_restore_legal(target text,expected_lock bigint,revision_id uuid) returns uuid language sql security invoker set search_path='' as $$select unseen_private.change_legal_document(target,expected_lock,'restore',null,revision_id)$$;
create function public.admin_legal_state() returns jsonb language plpgsql security invoker set search_path='' as $$
begin
 if not unseen_private.is_admin() then raise insufficient_privilege using message='Administrator session required';end if;
 return jsonb_build_object('documents',(select coalesce(jsonb_agg(to_jsonb(d) order by document_key),'[]'::jsonb) from public.legal_documents d),'revisions',(select coalesce(jsonb_agg(to_jsonb(r)-'content' order by document_key,version desc),'[]'::jsonb) from public.legal_revisions r),'events',(select coalesce(jsonb_agg(to_jsonb(e) order by created_at desc),'[]'::jsonb) from public.legal_events e));
end $$;
revoke all on function public.admin_save_legal_draft(text,bigint,jsonb),public.admin_publish_legal(text,bigint,uuid),public.admin_revoke_legal(text,bigint,uuid),public.admin_restore_legal(text,bigint,uuid),public.admin_legal_state() from public,anon,authenticated;
grant execute on function public.admin_save_legal_draft(text,bigint,jsonb),public.admin_publish_legal(text,bigint,uuid),public.admin_revoke_legal(text,bigint,uuid),public.admin_restore_legal(text,bigint,uuid),public.admin_legal_state() to authenticated;
comment on table public.legal_revisions is 'Immutable bilingual revisions; only approved, non-revoked snapshots are publicly readable. Approval is owner editorial publication, not external legal certification.';
comment on table public.legal_events is 'Append-only Admin actions with server-derived actor/time. No historical user Terms acceptance is recorded by this feature.';

-- END UNCHANGED ORIGINAL MIGRATION
DO $legal_seed_guard$
BEGIN
 if (select count(*) from public.legal_documents)<>2 or (select count(*) from public.legal_revisions)<>2 or exists(select 1 from public.legal_events) then raise exception 'Unexpected initial legal inventory; rollback';end if;
 if exists(select 1 from public.legal_revisions where version<>1 or approved_at is not null or revoked_at is not null or content->'review'<>'{"operator":false,"contact":false,"retention":false,"legalReview":false}'::jsonb or not unseen_private.valid_legal_content(content,true) or jsonb_array_length(content->'en'->'sections')<>case when document_key='privacy' then 12 else 14 end or jsonb_array_length(content->'ar-JO'->'sections')<>case when document_key='privacy' then 12 else 14 end) then raise exception 'Initial revisions must be exact complete bilingual unapproved review drafts; rollback';end if;
END $legal_seed_guard$;
SELECT document_key,version,approved_at,revoked_at FROM public.legal_revisions ORDER BY document_key;
COMMIT;
